-- Feed components -> tab Components, base year 2026. Generated by scripts/it-handover.mjs; do not edit.
-- Column 1 is ROW_KEY (unique; drop it from the data file). The other columns are in sheet order.
-- Components: one row per COMPONENT_CATALOG component (ME_EC / ME_MC). Yearly demand comes from KPI_COMPONENT_DEMAND_BY_YEAR (CTE D);
-- monthly demand (current and next year) from COMPONENT_DEMAND_FORECAST (CTE MO: M = 'YYYY-MM', summed then rounded to 2 decimals).
-- The final SELECT lists year and month columns interleaved through the SERIES template.
WITH DEMAND AS (
  SELECT
    PART_ID,
    BOOLOR_AGG(IS_SOURCED_BY_US) AS ANY_SOURCED
    , SUM(IFF(IS_SOURCED_BY_US AND DEMAND_YEAR = 2025, TOTAL_DEMAND, 0)) AS DEMAND_2025
, SUM(IFF(IS_SOURCED_BY_US AND DEMAND_YEAR = 2026, TOTAL_DEMAND, 0)) AS DEMAND_2026
, SUM(IFF(IS_SOURCED_BY_US AND DEMAND_YEAR = 2027, TOTAL_DEMAND, 0)) AS DEMAND_2027
, SUM(IFF(IS_SOURCED_BY_US AND DEMAND_YEAR = 2028, TOTAL_DEMAND, 0)) AS DEMAND_2028
, SUM(IFF(IS_SOURCED_BY_US AND DEMAND_YEAR = 2029, TOTAL_DEMAND, 0)) AS DEMAND_2029
, SUM(IFF(IS_SOURCED_BY_US AND DEMAND_YEAR = 2030, TOTAL_DEMAND, 0)) AS DEMAND_2030
, SUM(IFF(IS_SOURCED_BY_US AND DEMAND_YEAR = 2031, TOTAL_DEMAND, 0)) AS DEMAND_2031
, SUM(IFF(IS_SOURCED_BY_US AND DEMAND_YEAR = 2032, TOTAL_DEMAND, 0)) AS DEMAND_2032
, SUM(IFF(IS_SOURCED_BY_US AND DEMAND_YEAR = 2033, TOTAL_DEMAND, 0)) AS DEMAND_2033
, SUM(IFF(IS_SOURCED_BY_US AND DEMAND_YEAR = 2034, TOTAL_DEMAND, 0)) AS DEMAND_2034
, SUM(IFF(IS_SOURCED_BY_US AND DEMAND_YEAR = 2035, TOTAL_DEMAND, 0)) AS DEMAND_2035
, SUM(IFF(IS_SOURCED_BY_US AND DEMAND_YEAR = 2036, TOTAL_DEMAND, 0)) AS DEMAND_2036
  FROM MECL_PLATFORM.ANALYTICS.KPI_COMPONENT_DEMAND_BY_YEAR
  WHERE PART_KIND = 'COMPONENT'
  GROUP BY PART_ID
),
MO AS (
  SELECT
    PART_ID
    , SUM(IFF(M = '2026-01', DEMAND_QUANTITY, 0))::NUMBER(38,2) AS M_2026_01
, SUM(IFF(M = '2026-02', DEMAND_QUANTITY, 0))::NUMBER(38,2) AS M_2026_02
, SUM(IFF(M = '2026-03', DEMAND_QUANTITY, 0))::NUMBER(38,2) AS M_2026_03
, SUM(IFF(M = '2026-04', DEMAND_QUANTITY, 0))::NUMBER(38,2) AS M_2026_04
, SUM(IFF(M = '2026-05', DEMAND_QUANTITY, 0))::NUMBER(38,2) AS M_2026_05
, SUM(IFF(M = '2026-06', DEMAND_QUANTITY, 0))::NUMBER(38,2) AS M_2026_06
, SUM(IFF(M = '2026-07', DEMAND_QUANTITY, 0))::NUMBER(38,2) AS M_2026_07
, SUM(IFF(M = '2026-08', DEMAND_QUANTITY, 0))::NUMBER(38,2) AS M_2026_08
, SUM(IFF(M = '2026-09', DEMAND_QUANTITY, 0))::NUMBER(38,2) AS M_2026_09
, SUM(IFF(M = '2026-10', DEMAND_QUANTITY, 0))::NUMBER(38,2) AS M_2026_10
, SUM(IFF(M = '2026-11', DEMAND_QUANTITY, 0))::NUMBER(38,2) AS M_2026_11
, SUM(IFF(M = '2026-12', DEMAND_QUANTITY, 0))::NUMBER(38,2) AS M_2026_12
, SUM(IFF(M = '2027-01', DEMAND_QUANTITY, 0))::NUMBER(38,2) AS M_2027_01
, SUM(IFF(M = '2027-02', DEMAND_QUANTITY, 0))::NUMBER(38,2) AS M_2027_02
, SUM(IFF(M = '2027-03', DEMAND_QUANTITY, 0))::NUMBER(38,2) AS M_2027_03
, SUM(IFF(M = '2027-04', DEMAND_QUANTITY, 0))::NUMBER(38,2) AS M_2027_04
, SUM(IFF(M = '2027-05', DEMAND_QUANTITY, 0))::NUMBER(38,2) AS M_2027_05
, SUM(IFF(M = '2027-06', DEMAND_QUANTITY, 0))::NUMBER(38,2) AS M_2027_06
, SUM(IFF(M = '2027-07', DEMAND_QUANTITY, 0))::NUMBER(38,2) AS M_2027_07
, SUM(IFF(M = '2027-08', DEMAND_QUANTITY, 0))::NUMBER(38,2) AS M_2027_08
, SUM(IFF(M = '2027-09', DEMAND_QUANTITY, 0))::NUMBER(38,2) AS M_2027_09
, SUM(IFF(M = '2027-10', DEMAND_QUANTITY, 0))::NUMBER(38,2) AS M_2027_10
, SUM(IFF(M = '2027-11', DEMAND_QUANTITY, 0))::NUMBER(38,2) AS M_2027_11
, SUM(IFF(M = '2027-12', DEMAND_QUANTITY, 0))::NUMBER(38,2) AS M_2027_12
  FROM (
    SELECT PART_ID, TO_CHAR(MONTH_START, 'YYYY-MM') AS M, DEMAND_QUANTITY
    FROM MECL_PLATFORM.ANALYTICS.COMPONENT_DEMAND_FORECAST
    WHERE IS_SOURCED_BY_US AND PART_KIND = 'COMPONENT'
  )
  GROUP BY PART_ID
),
MS AS (
  SELECT
    COMPONENT_ID,
    LISTAGG(DISTINCT MS_PART_NUMBER, ', ') WITHIN GROUP (ORDER BY MS_PART_NUMBER) AS ME_MS,
    MAX(MS_PART_NUMBER) AS PRIMARY_ME_MS
  FROM MECL_PLATFORM.ANALYTICS.MULTISOURCE_PART_MEMBERS
  WHERE IS_USABLE
  GROUP BY COMPONENT_ID
),
EMS AS (
  SELECT
    PRIMARY_COMPONENT_ID AS COMPONENT_ID,
    LISTAGG(DISTINCT EMS_CODE || ':' || EMS_PART, ', ') WITHIN GROUP (ORDER BY EMS_CODE || ':' || EMS_PART) AS EMS_PART_NUMBERS
  FROM MECL_PLATFORM.ANALYTICS.SC_EMS_PART
  WHERE IS_IN_LATEST_SNAPSHOT AND PRIMARY_COMPONENT_ID IS NOT NULL
  GROUP BY PRIMARY_COMPONENT_ID
)
SELECT
  C.SUPPLIER_PARTNUMBER AS ROW_KEY,
  C.SUPPLIER_PARTNUMBER AS ME_EC,
  C.MANUFACTURER_NAME AS MANUFACTURER,
  C.MANUFACTURER_PARTNUMBER AS MPN,
  COALESCE(NULLIF(C.CORE_DESCRIPTION, ''), NULLIF(C.HW_DESCRIPTION, '')) AS DESCRIPTION,
  C.HW_CATEGORY AS HW_CATEGORY,
  C.HW_SUBCATEGORY AS HW_SUBCATEGORY,
  C.COMPONENT_STATUS AS COMPONENT_STATUS,
  COALESCE(NULLIF(C.HW_LIFECYCLE, ''), NULLIF(C.SE_LIFECYCLE, '')) AS LIFECYCLE,
  C.YEARS_TO_END_OF_LIFE::FLOAT AS YEARS_TO_EOL,
  MS.ME_MS AS ME_MS,
  MS.PRIMARY_ME_MS AS PRIMARY_ME_MS,
  EMS.EMS_PART_NUMBERS AS EMS_PART_NUMBERS,
  COALESCE(D.ANY_SOURCED, FALSE) AS IS_SOURCED_BY_US
  , COALESCE(D.DEMAND_2025, 0) AS DEMAND_2025
, COALESCE(MO.M_2026_01, 0) AS M_2026_01
, COALESCE(MO.M_2026_02, 0) AS M_2026_02
, COALESCE(MO.M_2026_03, 0) AS M_2026_03
, COALESCE(MO.M_2026_04, 0) AS M_2026_04
, COALESCE(MO.M_2026_05, 0) AS M_2026_05
, COALESCE(MO.M_2026_06, 0) AS M_2026_06
, COALESCE(MO.M_2026_07, 0) AS M_2026_07
, COALESCE(MO.M_2026_08, 0) AS M_2026_08
, COALESCE(MO.M_2026_09, 0) AS M_2026_09
, COALESCE(MO.M_2026_10, 0) AS M_2026_10
, COALESCE(MO.M_2026_11, 0) AS M_2026_11
, COALESCE(MO.M_2026_12, 0) AS M_2026_12
, COALESCE(D.DEMAND_2026, 0) AS DEMAND_2026
, COALESCE(MO.M_2027_01, 0) AS M_2027_01
, COALESCE(MO.M_2027_02, 0) AS M_2027_02
, COALESCE(MO.M_2027_03, 0) AS M_2027_03
, COALESCE(MO.M_2027_04, 0) AS M_2027_04
, COALESCE(MO.M_2027_05, 0) AS M_2027_05
, COALESCE(MO.M_2027_06, 0) AS M_2027_06
, COALESCE(MO.M_2027_07, 0) AS M_2027_07
, COALESCE(MO.M_2027_08, 0) AS M_2027_08
, COALESCE(MO.M_2027_09, 0) AS M_2027_09
, COALESCE(MO.M_2027_10, 0) AS M_2027_10
, COALESCE(MO.M_2027_11, 0) AS M_2027_11
, COALESCE(MO.M_2027_12, 0) AS M_2027_12
, COALESCE(D.DEMAND_2027, 0) AS DEMAND_2027
, COALESCE(D.DEMAND_2028, 0) AS DEMAND_2028
, COALESCE(D.DEMAND_2029, 0) AS DEMAND_2029
, COALESCE(D.DEMAND_2030, 0) AS DEMAND_2030
, COALESCE(D.DEMAND_2031, 0) AS DEMAND_2031
, COALESCE(D.DEMAND_2032, 0) AS DEMAND_2032
, COALESCE(D.DEMAND_2033, 0) AS DEMAND_2033
, COALESCE(D.DEMAND_2034, 0) AS DEMAND_2034
, COALESCE(D.DEMAND_2035, 0) AS DEMAND_2035
, COALESCE(D.DEMAND_2036, 0) AS DEMAND_2036
FROM MECL_PLATFORM.ANALYTICS.COMPONENT_CATALOG C
LEFT JOIN DEMAND D ON D.PART_ID = C.COMPONENT_ID
LEFT JOIN MO ON MO.PART_ID = C.COMPONENT_ID
LEFT JOIN MS ON MS.COMPONENT_ID = C.COMPONENT_ID
LEFT JOIN EMS ON EMS.COMPONENT_ID = C.COMPONENT_ID
ORDER BY ROW_KEY;
